create table if not exists public.events(id bigint generated by default as identity primary key,day text,month text,title text not null,date text,description text,image text,sort_order int default 0);
create table if not exists public.gallery(id bigint generated by default as identity primary key,title text not null,image_url text not null,created_at timestamptz default now());
create table if not exists public.committee(id bigint generated by default as identity primary key,name text not null,role text not null,image_url text,sort_order int default 0);
alter table public.events enable row level security; alter table public.gallery enable row level security; alter table public.committee enable row level security;
create policy "public read events" on public.events for select using(true);
create policy "public read gallery" on public.gallery for select using(true);
create policy "public read committee" on public.committee for select using(true);
create policy "auth insert gallery" on public.gallery for insert to authenticated with check(true);
insert into storage.buckets(id,name,public) values('gallery','gallery',true) on conflict(id) do nothing;
create policy "public view gallery files" on storage.objects for select using(bucket_id='gallery');
create policy "auth upload gallery files" on storage.objects for insert to authenticated with check(bucket_id='gallery');
